import math

import numpy as np

from ...image_processing_backends import PilBackend
from ...image_processing_utils import BatchFeature
from ...image_transforms import resize
from ...image_utils import ImageInput, PILImageResampling
from ...processing_utils import ImagesKwargs, Unpack
from ...utils import (
    TensorType,
    auto_docstring,
)


_SUPPORTED_SOFT_TOKENS = (70, 140, 280, 560, 1120)


class Gemma4UnifiedImageProcessorKwargs(ImagesKwargs, total=False):
    """
    patch_size (`int`, *optional*):
        Size of each teacher image patch in pixels (before merging).
    max_soft_tokens (`int`, *optional*):
        Maximum number of soft (vision) tokens per image after patch merging.
        Must be one of {70, 140, 280, 560, 1120}.
    pooling_kernel_size (`int`, *optional*):
        Kernel size for merging teacher patches into model patches.
    """

    patch_size: int
    max_soft_tokens: int
    pooling_kernel_size: int


def get_aspect_ratio_preserving_size(
    height: int,
    width: int,
    patch_size: int,
    max_patches: int,
    pooling_kernel_size: int,
) -> tuple[int, int]:
    """
    Image is resized to preserve aspect ratio so it fits within the patch budget.
    Target dimensions are the largest that:
    1) Produce at most `max_patches` patches when patchified with `patch_size`
    2) Have height and width divisible by `pooling_kernel_size * patch_size`
    """
    total_px = height * width
    target_px = max_patches * (patch_size**2)
    factor = math.sqrt(target_px / total_px)
    ideal_height = factor * height
    ideal_width = factor * width
    side_mult = pooling_kernel_size * patch_size

    # Round down to nearest multiple of side_mult
    target_height = int(math.floor(ideal_height / side_mult)) * side_mult
    target_width = int(math.floor(ideal_width / side_mult)) * side_mult

    # Handle edge cases where one or both dimensions round to 0
    if target_height == 0 and target_width == 0:
        raise ValueError(
            "Attempting to resize to a 0 x 0 image. Resized height should be divisible by "
            f"`pooling_kernel_size * patch_size`={pooling_kernel_size * patch_size}."
        )

    max_side_length = (max_patches // pooling_kernel_size**2) * side_mult
    if target_height == 0:
        target_height = side_mult
        target_width = min(
            int(math.floor(width / height)) * side_mult,
            max_side_length,
        )
    elif target_width == 0:
        target_width = side_mult
        target_height = min(
            int(math.floor(height / width)) * side_mult,
            max_side_length,
        )

    if target_height * target_width > target_px:
        raise ValueError(
            f"Resizing [{height}x{width}] to [{target_height}x{target_width}] "
            f"but this exceeds {max_patches} patches with patch_size {patch_size}"
        )

    return target_height, target_width


def convert_image_to_merged_patches(
    image: np.ndarray, patch_size: int, pooling_kernel_size: int
) -> tuple[np.ndarray, np.ndarray]:
    """
    Convert a (num_channels, height, width) image into merged model patches and their XY positions.

    Gives the same result as patchifying with `patch_size` and merging each k×k group with `patches_merge`:
    a merged patch is one `(k * patch_size)` square of the image, flattened in (row, column, channel) order.

    Returns:
        patches: (num_model_patches, (k * patch_size)² × num_channels)
        positions: (num_model_patches, 2) — XY position of each merged patch.
    """
    model_patch_size = patch_size * pooling_kernel_size
    num_channels, image_height, image_width = image.shape
    num_patches_height = image_height // model_patch_size
    num_patches_width = image_width // model_patch_size
    patches = image.reshape(num_channels, num_patches_height, model_patch_size, num_patches_width, model_patch_size)
    patches = patches.transpose(1, 3, 2, 4, 0).reshape(num_patches_height * num_patches_width, -1)

    grid_x, grid_y = np.meshgrid(np.arange(num_patches_width), np.arange(num_patches_height), indexing="xy")
    positions = np.stack([grid_x, grid_y], axis=-1).reshape(-1, 2)
    return patches, positions


@auto_docstring(custom_intro="Constructs a Gemma4 unified image processor.")
class Gemma4UnifiedImageProcessorPil(PilBackend):
    valid_kwargs = Gemma4UnifiedImageProcessorKwargs
    model_input_names = ["pixel_values", "image_position_ids", "num_soft_tokens_per_image"]

    do_resize = True
    resample = PILImageResampling.BICUBIC
    do_rescale = True
    rescale_factor = 1 / 255
    do_normalize = False
    image_mean = [0.0, 0.0, 0.0]
    image_std = [1.0, 1.0, 1.0]
    do_convert_rgb = True
    patch_size = 16
    max_soft_tokens = 280
    pooling_kernel_size = 3

    def __init__(self, **kwargs: Unpack[Gemma4UnifiedImageProcessorKwargs]) -> None:
        super().__init__(**kwargs)

        if self.max_soft_tokens not in _SUPPORTED_SOFT_TOKENS:
            raise ValueError(f"`max_soft_tokens` must be one of {_SUPPORTED_SOFT_TOKENS}, got {self.max_soft_tokens}.")

    def _validate_preprocess_kwargs(self, **kwargs):
        # Gemma4Unified uses aspect_ratio_preserving_resize driven by patch_size,
        # max_soft_tokens, and pooling_kernel_size — not the standard `size`
        # parameter. Temporarily disable do_resize so the base validation
        # doesn't require `size` to be set.
        kwargs["do_resize"] = False
        super()._validate_preprocess_kwargs(**kwargs)

    @auto_docstring
    def preprocess(
        self,
        images: ImageInput,
        **kwargs: Unpack[Gemma4UnifiedImageProcessorKwargs],
    ) -> BatchFeature:
        return super().preprocess(images, **kwargs)

    def aspect_ratio_preserving_resize(
        self,
        image: np.ndarray,
        patch_size: int,
        max_patches: int,
        pooling_kernel_size: int,
        resample: PILImageResampling,
    ) -> np.ndarray:
        height, width = image.shape[-2], image.shape[-1]
        target_height, target_width = get_aspect_ratio_preserving_size(
            height=height,
            width=width,
            patch_size=patch_size,
            max_patches=max_patches,
            pooling_kernel_size=pooling_kernel_size,
        )

        if target_height == height and target_width == width:
            return image

        return resize(
            image,
            size=(target_height, target_width),
            resample=resample,
        )

    def _preprocess(
        self,
        images: list[np.ndarray],
        do_resize: bool,
        resample: "PILImageResampling | int | None",
        do_rescale: bool,
        rescale_factor: float,
        do_normalize: bool,
        image_mean: float | list[float] | None,
        image_std: float | list[float] | None,
        return_tensors: str | TensorType | None,
        max_soft_tokens: int | None = None,
        patch_size: int | None = None,
        pooling_kernel_size: int | None = None,
        **kwargs,
    ) -> BatchFeature:
        if max_soft_tokens not in _SUPPORTED_SOFT_TOKENS:
            raise ValueError(f"`max_soft_tokens` must be one of {_SUPPORTED_SOFT_TOKENS}, got {max_soft_tokens}.")

        # Compute max_patches from max_soft_tokens and pooling_kernel_size
        max_patches = max_soft_tokens * pooling_kernel_size**2

        pixel_values = []
        position_ids = []
        num_soft_tokens_per_image = []

        for image in images:
            # Step 1: Aspect-ratio-preserving resize
            if do_resize:
                image = self.aspect_ratio_preserving_resize(
                    image=image,
                    patch_size=patch_size,
                    max_patches=max_patches,
                    pooling_kernel_size=pooling_kernel_size,
                    resample=resample,
                )

            # Step 2: Rescale pixel values from [0, 255] to [0, 1]
            if do_rescale:
                image = self.rescale(image=image, scale=rescale_factor)

            # Step 3: Identity normalization because Gemma4 was trained with pixels in [0, 1]
            if do_normalize:
                image = self.normalize(image=image, mean=image_mean, std=image_std)

            # Step 4: Patchify straight into merged model patches (k×k teacher patches each)
            merged_patches, merged_positions = convert_image_to_merged_patches(image, patch_size, pooling_kernel_size)
            num_soft_tokens_per_image.append(merged_patches.shape[0])

            # Step 5: Pad merged patches with zeros and positions with -1 up to max_soft_tokens
            padding_length = max_soft_tokens - merged_patches.shape[0]
            merged_patches = np.pad(merged_patches, [(0, padding_length), (0, 0)], constant_values=0)
            merged_positions = np.pad(merged_positions, [(0, padding_length), (0, 0)], constant_values=-1)
            pixel_values.append(merged_patches)
            position_ids.append(merged_positions)

        # Stack into batch arrays
        pixel_values = np.stack(pixel_values, axis=0)  # (batch, max_soft_tokens, model_patch_size²*3)
        position_ids = np.stack(position_ids, axis=0)  # (batch, max_soft_tokens, 2)

        data = {
            "pixel_values": pixel_values,
            "image_position_ids": position_ids,
            "num_soft_tokens_per_image": num_soft_tokens_per_image,
        }
        return BatchFeature(data=data, tensor_type=return_tensors)


__all__ = ["Gemma4UnifiedImageProcessorPil"]
